# Curated LeetCode practice tiers for the level picker.
#
# These three lists are NOT an official LeetCode export. Level 1 mirrors
# the well-known community 'Blind 75' set (sourced from
# data/leetcode/Blind_75_Company_Tags.xlsx). Levels 2 and 3 are curated by
# RepoSense, modeled loosely on the spirit of LeetCode's 'Top Interview 150'
# and the NeetCode 250 roadmap, to give a longer progression path. Each tier
# is a strict superset of the previous one: Level 1 (75) subset of Level 2
# (150) subset of Level 3 (250).
#
# `solvable` marks whether the problem has real test cases wired up to the
# in-app judge (see services/leetcode_service.py). Problems without an
# in-app judge link out to the real LeetCode problem page instead.
#
# `companies` lists employers reported to have asked this exact problem,
# sourced from a public community-maintained company-tag dataset
# (github.com/hxu296/leetcode-company-wise-problems-2022), cross-referenced
# by problem slug. 230 of these 250 problems have at least one tag; the
# other 20 simply weren't present in that dataset, so the list is empty
# rather than guessed.

from dataclasses import dataclass, field
from typing import Optional


@dataclass
class LevelProblem:
    slug: str
    title: str
    category: str
    difficulty: str
    leetcode_url: str
    solvable: bool
    companies: list[str] = field(default_factory=list)


def _p(slug: str, title: str, category: str, difficulty: str, leetcode_url: str, solvable: bool = False, companies: Optional[list[str]] = None) -> LevelProblem:
    return LevelProblem(slug=slug, title=title, category=category, difficulty=difficulty, leetcode_url=leetcode_url, solvable=solvable, companies=companies or [])


