LEVELS = {
    "level-1": {
        "key": "level-1",
        "label": "Level 1 \u2022 Blind 75",
        "description": "The classic Blind 75 \u2014 the tightest, highest-signal set for interview prep.",
        "problems": _LEVEL_1_PROBLEMS,
    },
    "level-2": {
        "key": "level-2",
        "label": "Level 2 \u2022 Top 150",
        "description": "Blind 75 plus 75 more, modeled on LeetCode\u2019s Top Interview 150. Not an official LeetCode list.",
        "problems": _LEVEL_2_PROBLEMS,
    },
    "level-3": {
        "key": "level-3",
        "label": "Level 3 \u2022 Top 250",
        "description": "The full grind \u2014 150 plus 100 more, modeled on the NeetCode 250 roadmap. Not an official LeetCode list.",
        "problems": _LEVEL_3_PROBLEMS,
    },
}


def get_level(level_key: str) -> Optional[dict]:
    return LEVELS.get(level_key)


def list_levels() -> list[dict]:
    return [
        {
            "key": lvl["key"],
            "label": lvl["label"],
            "description": lvl["description"],
            "count": len(lvl["problems"]),
        }
        for lvl in LEVELS.values()
    ]


def list_all_companies() -> list[str]:
    """All distinct company names tagged anywhere across the three tiers, sorted."""
    seen: set[str] = set()
    for lvl in LEVELS.values():
        for p in lvl["problems"]:
            seen.update(p.companies)
    return sorted(seen)
